class _Domain:
    """Stands in for openmc.Cell / openmc.Material: an id and a name."""
    def __init__(self, id, name):
        self.id = id
        self.name = name

def _arr(s):
    return np.frombuffer(zlib.decompress(base64.b64decode(s)), dtype='<i4')

V_PIX, H_PIX = 1560, 1560
_CELLS = ''
_MATS = ''
id_map = np.zeros((V_PIX, H_PIX, 3), dtype=np.int32)
id_map[:, :, 0] = _arr(_CELLS).reshape(V_PIX, H_PIX)
id_map[:, :, 1] = np.where(id_map[:, :, 0] < 0, id_map[:, :, 0], 0)  # instance: not used by the plot
id_map[:, :, 2] = _arr(_MATS).reshape(V_PIX, H_PIX)
import os
if os.environ.get('OUTRAM_IDMAP_OUT'):  # verification hook, draws nothing
    np.save(os.environ['OUTRAM_IDMAP_OUT'], id_map)

basis = 'xy'
x, y, z = 0, 1, 2
origin = (0.0, 0.0, 110.909)
width = (390.0, 390.0)
pixels = (1560, 1560)
color_by = 'material'
axis_units = 'cm'
legend = True
outline = False
overlap_color = (255, 0, 0)
plane_tolerance = 1.0
colors = {
    _Domain(70, "HELIUM"): (205, 230, 255),
    _Domain(71, "REFLECTOR GRAPHITE"): (150, 115, 80),
    _Domain(72, "BORONATED CARBON"): (130, 40, 160),
}
legend_kwargs = {"fontsize": 'small'}
source_kwargs = {}
